data.content:
{
  "cases": [
    {
      "id": "G01",
      "intentClass": "STATE_PREPARATION",
      "rawPrompt": "我发你一份社区花园的种植记录和几封居民来信，你先看看，熟悉一下里面的种植习惯和矛盾点，我晚点再跟你讨论怎么调整明年的种植计划。",
      "context": "用户是社区花园协调员，手头有2023-2024年的种植日志（记录每块地种了什么、收成如何）和五封居民来信（有的抱怨光照被挡，有的希望增加香草区，有的提到浇水分配不均）。用户希望助手先消化这些材料，理解种植习惯和主要矛盾，但尚未提出具体调整方案。当前阶段只需助手表示已接收并理解材料，后续再讨论计划。",
      "acceptance": {
        "hardRequirements": [
          "助手需明确表示已接收并开始熟悉材料",
          "助手需简要概括材料涉及的核心内容（如种植记录、居民来信、矛盾点）",
          "助手不得在此时提出具体的种植调整方案或要求用户补充信息"
        ],
        "acceptableVariants": [
          "助手可提及已注意到种植习惯和矛盾点，但无需展开细节",
          "助手可询问用户希望何时讨论，但不强制"
        ],
        "meaningfulGain": [
          "助手能准确识别材料类型和用户意图是准备阶段",
          "助手反馈自然简短，不生成独立说明文档"
        ]
      }
    },
    {
      "id": "G02",
      "intentClass": "STATE_PREPARATION",
      "rawPrompt": "这是我家老宅翻修前拍的结构照片和一份手写的改造想法清单，你先过一遍，把房屋现状和我想改的地方理一理，等周末我再跟你细聊怎么跟施工队沟通。",
      "context": "用户准备翻修老宅，提供了结构照片（显示承重墙、门窗位置、破损情况）和手写清单（列出想拆的隔墙、想扩大的窗户、想保留的老物件）。用户希望助手先熟悉这些材料，理解房屋现状和改造意图，但尚未要求助手给出沟通策略或施工建议。当前阶段只需助手表示已了解材料内容，后续再讨论。",
      "acceptance": {
        "hardRequirements": [
          "助手需确认已接收并浏览材料",
          "助手需简要提及材料包含结构照片和改造想法清单",
          "助手不得在此时提供施工沟通建议或改造方案"
        ],
        "acceptableVariants": [
          "助手可概括一两个改造意图作为理解证明，但不展开",
          "助手可表示等待用户后续细聊"
        ],
        "meaningfulGain": [
          "助手能区分准备阶段与执行阶段",
          "助手反馈简洁，不越界输出方案"
        ]
      }
    },
    {
      "id": "G03",
      "intentClass": "STATE_PREPARATION",
      "rawPrompt": "我传给你一份方言录音的转写文本和对应的普通话翻译草稿，你先熟悉一下里面的词汇对照和语气差异，我之后要跟你商量怎么修订翻译。",
      "context": "用户是语言研究者，提供了方言录音的转写文本（含地方特色词汇和语气词）以及一份普通话翻译草稿（部分词汇翻译生硬，语气丢失）。用户希望助手先消化这些材料，理解词汇对照和语气差异，但尚未要求助手提出修订建议。当前阶段只需助手表示已接收并理解材料特点，后续再讨论修订。",
      "acceptance": {
        "hardRequirements": [
          "助手需确认已接收转写文本和翻译草稿",
          "助手需简要提及材料涉及方言词汇和语气差异",
          "助手不得在此时提出具体的翻译修订建议"
        ],
        "acceptableVariants": [
          "助手可举例说明注意到某个词汇或语气差异，但不深入",
          "助手可表示等待用户后续商量"
        ],
        "meaningfulGain": [
          "助手能识别材料类型和准备意图",
          "助手反馈不生成修订方案"
        ]
      }
    },
    {
      "id": "G04",
      "intentClass": "STATE_PREPARATION",
      "rawPrompt": "我发你一份婚礼流程表和双方家庭的习俗备注，你先看看，把时间节点和可能冲突的习俗记一下，我过两天再跟你讨论怎么协调。",
      "context": "用户正在筹备婚礼，提供了流程表（含仪式、宴席、拍照等时间安排）和双方家庭习俗备注（如敬茶顺序、红包金额、座位安排等存在差异）。用户希望助手先熟悉材料，理解时间节点和习俗冲突点，但尚未要求助手提出协调方案。当前阶段只需助手表示已了解材料内容，后续再讨论。",
      "acceptance": {
        "hardRequirements": [
          "助手需确认已接收流程表和习俗备注",
          "助手需简要提及材料涉及时间节点和习俗差异",
          "助手不得在此时提出具体的协调方案"
        ],
        "acceptableVariants": [
          "助手可概括一两个潜在冲突点作为理解证明，但不展开",
          "助手可表示等待用户后续讨论"
        ],
        "meaningfulGain": [
          "助手能准确识别准备阶段",
          "助手反馈自然，不越界给方案"
        ]
      }
    },
    {
      "id": "G05",
      "intentClass": "STATE_PREPARATION",
      "rawPrompt": "这是我从旧书摊淘来的一本手写菜谱的扫描件和几页食材笔记，你先翻翻，熟悉一下里面的菜品和特殊用料，我下周再跟你聊怎么整理成电子版。",
      "context": "用户收集了一本手写菜谱的扫描件（字迹潦草，含地方菜和家常菜）和几页食材笔记（记录特殊用料和替代方案）。用户希望助手先熟悉材料，理解菜品内容和特殊用料，但尚未要求助手提出整理方案。当前阶段只需助手表示已接收并浏览材料，后续再讨论电子化整理。",
      "acceptance": {
        "hardRequirements": [
          "助手需确认已接收扫描件和食材笔记",
          "助手需简要提及材料涉及手写菜谱和特殊用料",
          "助手不得在此时提出具体的整理或电子化方案"
        ],
        "acceptableVariants": [
          "助手可提及注意到字迹或用料特点，但不深入",
          "助手可表示等待用户后续讨论"
        ],
        "meaningfulGain": [
          "助手能识别材料类型和准备意图",
          "助手反馈简洁，不生成整理方案"
        ]
      }
    },
    {
      "id": "G06",
      "intentClass": "STATE_PREPARATION",
      "rawPrompt": "我发你一份社区合唱团的排练录音片段和团员出勤表，你先听听看看，熟悉一下各声部的情况和出勤规律，我之后要跟你商量怎么调整排练安排。",
      "context": "用户是社区合唱团组织者，提供了排练录音片段（各声部演唱片段）和团员出勤表（记录每次排练的出席情况）。用户希望助手先熟悉材料，理解各声部表现和出勤规律，但尚未要求助手提出调整建议。当前阶段只需助手表示已接收并了解材料内容，后续再讨论排练安排调整。",
      "acceptance": {
        "hardRequirements": [
          "助手需确认已接收录音片段和出勤表",
          "助手需简要提及材料涉及声部情况和出勤规律",
          "助手不得在此时提出具体的排练调整建议"
        ],
        "acceptableVariants": [
          "助手可概括一两个声部或出勤特点作为理解证明，但不展开",
          "助手可表示等待用户后续商量"
        ],
        "meaningfulGain": [
          "助手能区分准备与执行阶段",
          "助手反馈不越界给调整方案"
        ]
      }
    },
    {
      "id": "G07",
      "intentClass": "REQUESTED_RESULT",
      "rawPrompt": "我写了一首关于城市夜晚的短诗，发给你看看。读完后请给我两句具体的反馈：一句说意象运用，一句说节奏感受。",
      "context": "用户创作了一首八行的短诗，主题是城市夜晚，包含霓虹、地铁、便利店等意象。用户明确要求助手阅读后给出两句具体反馈：一句针对意象运用，一句针对节奏感受。助手需要理解诗歌内容并直接提供这两句反馈，不能只表示已读或要求更多信息。",
      "acceptance": {
        "hardRequirements": [
          "助手需提供恰好两句反馈",
          "第一句需针对意象运用，第二句需针对节奏感受",
          "反馈需具体，结合诗歌内容，不能空泛"
        ],
        "acceptableVariants": [
          "反馈顺序可互换，但需明确对应意象和节奏",
          "反馈语气可鼓励或中性，但需具体"
        ],
        "meaningfulGain": [
          "助手能准确理解诗歌并给出针对性反馈",
          "反馈简洁，不展开成长篇评论"
        ]
      }
    },
    {
      "id": "G08",
      "intentClass": "REQUESTED_RESULT",
      "rawPrompt": "我需要一份面向小学生的‘垃圾分类’宣传海报的文案，包括一句口号和三条分类小贴士，请直接写出来。",
      "context": "用户是小学老师，需要为校园垃圾分类活动制作宣传海报，要求助手直接提供文案：一句朗朗上口的口号，以及三条适合小学生理解的分类小贴士。助手需理解需求并直接输出文案，不能只表示准备或询问更多细节。",
      "acceptance": {
        "hardRequirements": [
          "助手需提供一句口号",
          "助手需提供三条分类小贴士",
          "内容需适合小学生理解，语言简洁"
        ],
        "acceptableVariants": [
          "口号风格可活泼或押韵，小贴士可涵盖不同分类",
          "小贴士可用短句或列表形式"
        ],
        "meaningfulGain": [
          "助手能直接交付可用文案",
          "文案符合小学生认知水平"
        ]
      }
    },
    {
      "id": "G09",
      "intentClass": "REQUESTED_RESULT",
      "rawPrompt": "我设计了一个简单的桌游规则，但还没起名字。规则是玩家轮流抽卡、交换资源、完成订单。你觉得这个桌游适合叫什么名字？为什么？",
      "context": "用户设计了一款桌游，核心机制是抽卡、资源交换和完成订单，但尚未命名。用户以自然疑问询问助手认为适合叫什么名字以及理由。助手需理解规则并给出一个或多个名字建议及理由，不能只表示已读或要求更多信息。",
      "acceptance": {
        "hardRequirements": [
          "助手需给出至少一个桌游名字建议",
          "助手需说明理由，理由需结合规则机制",
          "不能只表示已读或要求更多信息"
        ],
        "acceptableVariants": [
          "可给出多个名字并分别说明理由",
          "名字风格可多样，但需与机制相关"
        ],
        "meaningfulGain": [
          "助手能基于规则提出贴切的名字",
          "理由清晰，体现对机制的理解"
        ]
      }
    },
    {
      "id": "G10",
      "intentClass": "REQUESTED_RESULT",
      "rawPrompt": "我下周要在家办一个十人左右的聚会，有大人也有小孩，你帮我设计一个下午的活动安排，包括时间、环节和需要准备的东西，直接给我一个可用的方案。",
      "context": "用户计划在家举办十人左右的聚会，参与者包括大人和小孩，时间是一个下午。用户明确委托助手自行设计一个可用的活动安排，包括时间分配、环节设计和准备物品清单。助手需直接输出完整方案，不能只表示准备或询问更多细节。",
      "acceptance": {
        "hardRequirements": [
          "助手需提供一份下午的活动安排",
          "安排需包含时间分配、环节设计和准备物品清单",
          "方案需考虑大人和小孩共同参与"
        ],
        "acceptableVariants": [
          "环节可包括游戏、手工、茶歇等，顺序可调整",
          "准备物品清单可简可详，但需覆盖主要环节"
        ],
        "meaningfulGain": [
          "助手能交付可直接执行的方案",
          "方案兼顾不同年龄参与者"
        ]
      }
    }
  ]
}
